def ford_fulkerson(graph, source, sink):
    n = len(graph)
    parent = [-1] * n
    min_additional = {i: float('inf') for i in range(n)}

    def bfs(u):
        queue = [u]
        min_additional[u] = 0
        while queue:
            u = queue.pop(0)
            if u == sink:
                return min_additional[sink]
            for v in range(n):
                if graph[u][v] > 0 and min_additional[v] == float('inf') and u != source:
                    min_additional[v] = graph[u][v] - parent[u]
                    queue.append(v)
        return None

    while bfs(source):
        u = min_additional[min_additional.keys()]
        while u != source:
            v = parent[u]
            uf = graph[u][v] + min_additional[v]
            if uf > graph[u][v]:
                graph[u][v] = graph[v][u] = uf
                parent[v] = u
                min_additional[v] -= uf - graph[u][v]
                min_additional[u] += uf - graph[u][v]
                u = v
