from heapq import heappush, heappop

def dijkstra(graph, start):
    distances = [float('inf')] * (n + 1)
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight, _ in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return distances

def solve(n, m, arcs):
    graph = [[] for _ in range(n + 1)]

    for x, y, w in arcs:
        graph[x].append((y, w, 'backward'))
        graph[y].append((x, w, 'forward'))

    forward_queue = []
    backward_queue = []

    for node in range(1, n + 1):
        if node < n:
            heappush(forward_queue, (0, 0, node))
        if node > 1:
            heappush(backward_queue, (1, 0, node))

    results = [i for i in range(n + 1)]

    while forward_queue:
        weight, _, node = heappop(forward_queue)
        forward_weight = weight // 2

        if node < n:
            results[node] = 1
        results[node] -= forward_weight

        for neighbor, weight, forward_component in graph[node]:
            if forward_weight + forward_component > results[neighbor]:
                results[neighbor] = forward_weight + forward_component
                heappush(forward_queue, (results[neighbor], forward_component, -neighbor))

    while backward_queue:
        weight, _, node = heappop(backward_queue)
        backward_weight = weight // 2

        if node > 1:
            results[node] = 1 - results[node]
        results[node] += backward_weight

        for neighbor, weight, backward_component in graph[node]:
            if backward_weight + backward_component > results[neighbor]:
                results[neighbor] = backward_weight + backward_component
                heappush(backward_queue, (results[neighbor], -backward_component, -neighbor))

    # Ensure all b_i are positive
    for i, weight in enumerate(graph[1 - n // 2][0]):
        results[1 - i] = weight // 2

    return results[:n]

