import sys

# Node class to represent a node in the graph
class Node:
    def __init__(self, value):
        self.value = value

# Edge class to represent an edge in the graph
class Edge:
    def __init__(self, destination, weight):
        self.destination = destination
        self.weight = weight

# Function to find the minimum cost to reach all nodes starting from a given node
def find_min_cost(start_node):
    # Initialize variables
    past = {}
    queue_f = [start_node]
    queue_s = []
    past[start_node] = 0

    # Perform Dijkstra's shortest path algorithm
    while queue_f:
        current_node = queue_f.pop(0)
        for child in current_node.neighbors:
            if past[child] < 0:
                past[child] = current_node.value + child.weight
                queue_s.append(child)
            elif past[child] > current_node.value + child.weight:
                past[child] = current_node.value + child.weight
                queue_f.append(child)
        if not queue_s:
            queue_f = queue_s
            queue_s = []
        else:
            queue_f = queue_f[1:]
    return past

# Input parsing function
def parse_input():
    n, m = map(int, sys.stdin.readline().strip().split())
    edges = [list(map(int, sys.stdin.readline().strip().split())) for _ in range(m)]
    return n, m, edges

# Output parsing function
def parse_output(min_cost):
    n = len(min_cost)
    return [f"{i+1} {min_cost[i]}" for i in range(n-1)] + [f"{n}"]

# Main function
def main():
    n, m = parse_input()
    nodes = [Node(i) for i in range(1, n+1)]
    edges = [Edge(nodes[i], w) for i, (x, y, w) in enumerate(edges) for j in [x, y]]
    start_node = nodes[0]
    past = find_min_cost(start_node)
    min_cost = [value for node, value in past.items() if past[node] > 0]
    if min_cost:
        min_cost = min(min_cost)
    else:
        min_cost = past[start_node]
    result = parse_output(list(past.values() | {min_cost}))
    print("\n".join(result))

if __name__ == "__main__":
    main()
