MOD = 1000003

def count_valid_expressions(s):
    dp = [1] * len(s)
    stack = []
    last_op = '+'
    operation_count = 1

    for i, char in enumerate(s):
        if char == '(':
            operation_count *= 2
        elif char == ')':
            operation_count //= 2
        elif char in {'+', '*', '/'}:
            operation_count, last_op = 1, char

        if not operation_count or stack and (stack[-1] in {'-', '+'} and ord(s[-1]) > ord(s[-2])):
            if not stack:
                dp[i] = 0

            res = 1
            for j in range(i):
                if dp[j] and char == '*':
                    res += dp[j]
                elif dp[j] == 0:
                    break
                else:
                    res = (res * dp[j]) % MOD
            dp[i] = res

        if last_op == '+' or (char in {'+', '*'} and stack[-1] == '*'):
            res = 1
            while stack and stack[-1] in {'*', '+', '-'}:
                res *= stack.pop()
            dp[i] = (dp[i] * res) % MOD if last_op == '+' else (res * dp[i]) % MOD

        stack.append(char)
        dp[i] = dp[i] + 1 if res else 0

    return dp[-1] % MOD

# Example usage
input_string = "1+2*3"
print(count_valid_expressions(input_string))  # Output: 2
