    for start in sorted(start_points):
        min_colors = max(min_colors, start)

    # Check consecutive end point for common color with adjacent interval ends
    for end in sorted(end_points):
        if end in end_points:
            for start in end - 1:
                if start in start_points:
                    min_colors = max(min_colors, start)
        for tail in end + 1:
