        end = ei + 1

        for i in range(start, ei):
            if points[start][i] > 1 or points[ei][i + 2] > 0:
                valid_colors.add(1)
                count[ei + 1][i + 2 - si] -= 1
            if points[start][i] < 1 or points[end][i + 2] <= 1:
                valid_colors.add(2)
                count[start][i + 1 - si] -= 1

    k = 1
    while k < len(intervals) and len(valid_colors) > 1:
        already_available_colors = set(valid_colors)
        valid_colors = {i for i in valid_colors if count[intervals.index(i) + 1][i + 2 - si] > 0 for si in range(1, intervals.index(i) + 1) for i in 
