        for c in range(3):
            ok = False
            if count[intervals.index(c) + 1][c] > 0 and not ok:
                valid_colors.remove(c)
            for ext_color in valid_colors:
                if count[intervals.index(c) + 1][c] >= count[intervals.index(ext_color) + 1][ext_color] + 1:
                    valid_colors.remove(ext_color)
            if len(valid_colors) > 0:
                ok = c
            elif len(valid_colors) == 0:
