from collections import defaultdict

def build_tree(n, edges):
    graph = defaultdict(list)
    visited = [False] * n
    level = [-1] * n
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        visited[u] = visited[v] = True
    for i in range(n):
        if not visited[i]:
            queue = [i]
            level[i] = 0
            while queue:
                node = queue.pop(0)
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        level[neighbor] = level[node] + 1
                        visited[neighbor] = True
                        queue.append(neighbor)
    return graph, level

def get_mex(n, level):
    result = [level[n]]
    curr_level = n
    while curr_level != level:
        for node in range(n):
            if curr_level % 2 == level[node]:
                next_level = (level[node] + 1) // 2
                result.append(next_level)
                curr_level = next_level
    return result

