def preprocess_tree(args):
    n = args[0]
    ndict = defaultdict(list)
    for line in args[1:]:
        u, v = map(int, line.split())
        ndict[u].append(v)
        ndict[v].append(u)

    result = [1] + [0] * n
    for k in range(n):
        if result[k] > n:
            break
        valid_mexacency_set = set()
        for u_neighbor in ndict[u]:
            if u_neighbor != result[k - 1]:
                if valid_mexacency_set and minkowski_distance(result[k - 1], valid_mexacency_set, 1) < minkowski_distance(u_neighbor, valid_mexacency_set, 1):
                    valid_mexacency_set = set([u_neighbor])
                else:
                    valid_mexacency_set.add(u_neighbor)
        for target in ndict[u]:
            if target != result[k]:
                result[target] = k + 1
    return result

