MOD = 10**9 + 7

def lcm(a, b):
    return a * b // gcd(a, b)

def find_min_position(s):
    digits = len(s)
    min_positions = [float('inf')] * (10**9 // len(s) + 1)
    for i in range(1, 10):
        prefix_len = 10 ** i
        lcm_set = set()
        for j in range(prefix_len):
            digits_to_match = list(s)
            j %= digits
            while digits_to_match and j >= len(digits_to_match):
                digits_to_match.pop()
            if digits_to_match:
                target = int("".join(digits_to_match))
                lcm_set.add((i, target))
        lcm_set |= {(i, target) for i, target in lcm_set}
        lcm_set.difference_update(((a, b) for a, b in lcm_set if a + i - b < 0 or (b % 2 and ((a + 1) % 2 or (b % 5 and b//10 % 2)) or (a % 7 and a//10 % 2))))
        merge_lcm = reduce(lcm, lcm_set)
        min_positions[merge_lcm] = min(min_positions[merge_lcm], i)
    return min_positions

def solve():
